fn prime_num(n: u64) -> bool {
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }

    // Only check odd divisors from 3 up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    let mut divisor = 3;

    while divisor <= limit {
        if n % divisor == 0 {
            return false;
        }
        divisor += 2;
    }

    true
}